def melody_distance(a, b, gap):
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]   # dp[i][j]: cost to turn a[:i] into b[:j]
    for i in range(1, n + 1):
        dp[i][0] = i * gap
    for j in range(1, m + 1):
        dp[0][j] = j * gap
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = min(dp[i - 1][j] + gap,                        # delete a[i-1]
                           dp[i][j - 1] + gap,                        # insert b[j-1]
                           dp[i - 1][j - 1] + abs(a[i - 1] - b[j - 1]))  # change
    return dp[n][m]
